  ('1b993014-23ef-5183-a9b7-7320f5f78f17', 'or-haneeman', 'אור הנאמ״ן', 'תוכנית הלכות והנהגות מתורת מרן הרב מאזוז זצ״ל. רשימה שנבנתה באתר מכותרות הערוץ ועמודי קול ברמה; אין בה טענה שכל התוכנית קיימת כאן.', 'system', null, 'published', 0),
  ('27894cbb-e341-5b42-aa00-e0b30c2769be', 'parasha-idea', 'רעיון מוסרי לפרשת השבוע', 'סרטונים שכותרתם מציינת רעיון מוסרי לפרשה או לחג. רשימה שנבנתה באתר.', 'system', null, 'published', 1),
  ('024d7332-dba6-5cb1-ab17-6d25fe1336a0', 'perek-yomi', 'הפרק היומי', 'המשך לימוד המשנה לזכר הרב מאזוז.', 'system', null, 'published', 2),
