insert into public.institutions (id, slug, name, description, source_urls, status) values
  ('60fe5dda-e6da-5eb9-aa28-3dff584bce3f', 'or-hameir', 'מוסדות אור המאיר', 'מקורות מוסדיים מתארים את הרב ליאור כהן כראש מוסדות אור המאיר באלעד.', '["https://www.ktr.org.il/post/_1110","https://www.youtube.com/channel/UCMnbrfOfK2Chfh7sGUiv_rA"]'::jsonb, 'published'),
  ('4cfcac1c-0f69-5375-abfb-38f2578204d1', 'maor-yosef', 'ישיבת מאור יוסף', 'מקורות מוסדיים מציגים את הרב כראש ישיבת מאור יוסף. לפי כתבת הייסוד זו ישיבה לצעירים, נפרדת מהישיבה הגדולה אורחות מאיר.', '["https://www.ktr.org.il/post/_1110"]'::jsonb, 'published'),
  ('cc966fda-0b76-50d1-a6f5-a4e6a48f2319', 'orchot-meir', 'הישיבה הגדולה אורחות מאיר', 'ישיבה גדולה שייסודה בראשות הרב מתועד בכתבה בכתר מלוכה.', '["https://www.ktr.org.il/post/_1110"]'::jsonb, 'published'),
  ('a183a930-7d96-5342-a1a1-13688cd5f9ff', 'heichal-moshe', 'קהילת היכל משה, רמת גן', 'נמצא תיעוד על קהילת היכל משה במגדל משה אביב ברמת גן. זמני שיעורים ופעילות כיום טרם אומתו.', '["https://www.ktr.org.il/post/__806-1"]'::jsonb, 'published')
