  ('67429a73-90da-5241-ae41-e7b460102928', 'דברי-הרב-בעצרת-לאחר-פטירת-חמיו-430835', null, 'דברי הרב בעצרת לאחר פטירת חמיו', null, null, 'מורשת ודברי התעוררות', '["https://www.ktr.org.il/post/__680-1"]'::jsonb, 'published'),
  ('ea3302df-5187-5f2c-ab6e-d2d6a382a6d7', 'עצרת-השלושים-באלעד-והפצת-כלי-מעקב-ללימוד-0e55a4', null, 'עצרת השלושים באלעד והפצת כלי מעקב ללימוד', null, null, 'מוזכרים פנקסי הוי שקוד של ארגון יאירו; קשר ניהולי לארגון לא אומת', '["https://www.ktr.org.il/post/__796"]'::jsonb, 'published'),
  ('fa8843ff-ad94-5054-a5b6-26223bc7a38a', 'קריאת-משלי-עם-הציבור-בחג-השבועות-c1feca', null, 'קריאת משלי עם הציבור בחג השבועות', null, null, 'דוגמה להמשך מסורת מעשית', '["https://www.ktr.org.il/post/__838","https://www.kore.co.il/viewArticle/185978"]'::jsonb, 'published'),
  ('3b0a93ea-24d1-541f-a1ec-ac34f44b51b4', 'הקראת-צוואת-הרב-מאזוז-ביום-ההלוויה-fa2841', null, 'הקראת צוואת הרב מאזוז ביום ההלוויה', null, null, 'מקור ללימוד משנה יומי ולהנחלת המורשת', '["https://www.ktr.org.il/post/__650"]'::jsonb, 'published'),
  ('291f0c7a-45c7-5815-aee8-a9b2dd9ec7dd', 'מעמד-הילולא-שהתקיים-בידי-מוסדות-אור-המאיר-22d578', '60fe5dda-e6da-5eb9-aa28-3dff584bce3f', 'מעמד הילולא שהתקיים בידי מוסדות אור המאיר', null, null, 'חומר לארכיון אירועים; נתון זמן הפרסום בתוצאת החיפוש אינו עקבי, ולכן לא נקבע תאריך', '["https://hm-news.co.il/625644/"]'::jsonb, 'published'),
  ('8a354c34-d7cf-586c-a38c-c78e61b8b6cf', 'עליית-הרב-לתפילה-בציון-רבי-שמעון-בר-יוחאי-73c4aa', null, 'עליית הרב לתפילה בציון רבי שמעון בר יוחאי', null, null, 'דף נקרא; זמן האירוע טעון בירור', '["https://www.ktr.org.il/post/1119"]'::jsonb, 'published'),
  ('c39c94cf-3968-598c-a1e7-44b949a483cc', 'הזמנה-להילולא-מרכזית-לרב-מאזוז-f72d81', null, 'הזמנה להילולא מרכזית לרב מאזוז', null, null, 'דף נקרא; תיעוד היסטורי ולא הזמנה תקפה כיום', '["https://www.ktr.org.il/post/_1061"]'::jsonb, 'published'),
  ('7f0afb82-f575-5340-a650-d6370cef7fa2', 'סיום-סדר-מועד-והודאה-על-שיבת-חטופים-0e24bc', null, 'סיום סדר מועד והודאה על שיבת חטופים', null, null, 'השתתפות הרב מתועדת', '["https://www.ktr.org.il/post/__856-1"]'::jsonb, 'published'),
  ('c8f9b07f-ce28-5e8a-a2ca-5ea10d5f2678', 'סיום-זרעים-ותחילת-מועד-בפרק-היומי-994d42', null, 'סיום זרעים ותחילת מועד בפרק היומי', null, null, 'נאומו והמשך מפעל הלימוד מתועדים', '["https://www.ktr.org.il/post/__668-1"]'::jsonb, 'published'),
  ('bcffcfd0-e106-5b9d-a71b-b1f975857f16', 'ביקור-בציון-הרב-מאזוז-בעקבות-חילול-המצבה-53b0ed', null, 'ביקור בציון הרב מאזוז בעקבות חילול המצבה', null, null, 'פעילות ציבורית היסטורית', '["https://www.ktr.org.il/post/__798-1"]'::jsonb, 'published'),
  ('7b1afd96-5afd-533d-abc5-53d12a5a752a', 'נישואי-נכד-הרב-מאזוז-בן-הרב-ליאור-50fba8', null, 'נישואי נכד הרב מאזוז, בן הרב ליאור', null, null, 'חומר חזותי ומשפחתי; אין צורך לפרסם כל פרט באתר', '["https://www.ktr.org.il/post/__132"]'::jsonb, 'draft'),
