insert into public.pages (id, slug, title, description, blocks, status) values
  ('ab117bf7-c6de-5a08-a804-c296b4469372', 'about', 'הרב והמוסדות', 'מידע מגובה מקורות על הרב ליאור כהן ומוסדות אור המאיר.', '[{"type":"paragraph","text":"הרב מופיע במקורות בעיקר בשם הרב ליאור כהן, ולעיתים ליאור הכהן. מקורות מוסדיים מתארים אותו כחתנו ונאמן ביתו של הרב מאיר מאזוז זצ״ל, ראש ישיבת מאור יוסף וראש מוסדות אור המאיר באלעד."},{"type":"quote","text":"ייסוד הישיבה הגדולה אורחות מאיר בראשותו","source":"כתר מלוכה — https://www.ktr.org.il/post/_1110"},{"type":"paragraph","text":"נמצא תיעוד על קהילת היכל משה במגדל משה אביב ברמת גן. זמני שיעורים ופעילות עדכניים טרם אומתו."},{"type":"heading","level":2,"text":"מה עדיין חסר"},{"type":"paragraph","text":"ביוגרפיה מאושרת, תמונה רשמית, פרטי קשר רשמיים של המוסדות ולוחות שיעורים עדכניים טרם התקבלו. פרטים אלה יתווספו רק לאחר אישור מטעם הרב או המוסדות."},{"type":"cta","label":"למוסדות ולפעילות המתועדת","href":"/institutions"}]'::jsonb, 'published'),
  ('f141f84f-f8bc-5647-afce-0beaf6297c08', 'accessibility', 'הצהרת נגישות', 'מצב הנגישות של האתר ודרכי פנייה.', '[{"type":"paragraph","text":"האתר נבנה במטרה לעמוד ברמה AA של הנחיות WCAG 2.2: ניווט מלא במקלדת, תוויות לשדות, ניגודיות צבעים, תמיכה בהגדלת טקסט וכיבוד העדפת \"הפחתת תנועה\"."},{"type":"paragraph","text":"בכל עמוד ניתן להפעיל \"הפחתת תנועה\" ולבחור מצב כהה או בהיר מתפריט התצוגה. אודיו ווידאו אינם מתנגנים אוטומטית."},{"type":"paragraph","text":"בדיקה מקיפה עם קוראי מסך טרם הושלמה. אם נתקלתם בקושי, נשמח לשמוע דרך טופס השאלות תחת הנושא \"פנייה כללית\"."}]'::jsonb, 'published'),
  ('01b7b22d-b507-5536-a1aa-633a8f39016a', 'privacy', 'מדיניות פרטיות', 'איזה מידע נשמר ואיך.', '[{"type":"paragraph","text":"אין צורך להירשם כדי לצפות, להאזין או לעיין. העדפות תצוגה, מועדפים והתקדמות האזנה נשמרים בדפדפן שלכם בלבד (localStorage) ואינם נשלחים אלינו."},{"type":"heading","level":2,"text":"שאלות לרב"},{"type":"paragraph","text":"שאלה נשלחת לצוות בלבד. אפשר לשאול בעילום שם. שאלה לא תפורסם ללא הסכמה נפרדת ומפורשת ורק לאחר אישור הרב. מספר המעקב והקוד הסודי מוצגים לכם פעם אחת; אנו שומרים רק גיבוב (hash) של הקוד ולא את הקוד עצמו."},{"type":"paragraph","text":"לצורך מניעת הצפה נשמר מזהה מגובב של הפונה לפרק זמן קצר. כתובת IP אינה נשמרת כטקסט גלוי."}]'::jsonb, 'published'),
  ('7b79f45a-0393-5117-abe9-16526f8d40d1', 'terms', 'תנאי שימוש', 'תנאי השימוש באתר.', '[{"type":"paragraph","text":"התכנים באתר מוצגים עם ייחוס למקורם. סרטוני YouTube מוצגים בנגן הרשמי בלבד. קבצים, תמונות והקלטות אינם מופצים מחדש אלא אם ניתנה לכך הרשאה."},{"type":"paragraph","text":"תשובות הלכתיות המוצגות באתר נמסרו לשואל מסוים ובנסיבות מסוימות. לשאלה מעשית יש לפנות לרב."}]'::jsonb, 'published'),
  ('5f63f634-5e18-54dc-ae53-c54573e23e78', 'contact', 'יצירת קשר', 'דרכי פנייה.', '[{"type":"paragraph","text":"פרטי קשר רשמיים של הרב ושל מוסדות אור המאיר טרם אומתו ולכן אינם מוצגים כאן."},{"type":"paragraph","text":"בינתיים ניתן לפנות דרך טופס השאלה — גם לפניות כלליות."},{"type":"cta","label":"לטופס הפנייה","href":"/ask"}]'::jsonb, 'published')
